#!/usr/bin/env node
/**
 * CI guard: detect drift between supabase/migrations/*.sql and
 * src/integrations/supabase/types.ts.
 *
 * `types.ts` is auto-regenerated by the Lovable platform when a migration is
 * applied. If a migration was committed but `types.ts` was NOT regenerated
 * (e.g. concurrent PRs, applied out-of-band, or local repro of a stale
 * checkout), the frontend compiles fine but breaks at runtime.
 *
 * This guard parses CREATE TABLE / ALTER TABLE ADD COLUMN statements from
 * migrations applied in the last N days (default 14) and checks each
 * referenced symbol is present in types.ts. Heuristic but catches the
 * common drift cases without needing DB access or a Supabase token.
 *
 * Usage:
 *   node scripts/security/check-types-drift.mjs           # fail on drift
 *   node scripts/security/check-types-drift.mjs --days 30 # widen window
 *
 * Exit codes:
 *   0  no drift detected
 *   1  drift detected (missing tables/columns in types.ts)
 *   2  invalid invocation
 */

import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";

const args = process.argv.slice(2);
const daysIdx = args.indexOf("--days");
const DAYS = daysIdx >= 0 ? parseInt(args[daysIdx + 1], 10) : 14;
if (Number.isNaN(DAYS) || DAYS < 1) {
  console.error("Invalid --days value");
  process.exit(2);
}

const MIG_DIR = "supabase/migrations";
const TYPES_FILE = "src/integrations/supabase/types.ts";

// Migration filename prefix is YYYYMMDDHHMMSS
function migrationDate(name) {
  const m = name.match(/^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})_/);
  if (!m) return null;
  const [, y, mo, d, h, mi, s] = m;
  return new Date(`${y}-${mo}-${d}T${h}:${mi}:${s}Z`);
}

const cutoff = new Date(Date.now() - DAYS * 24 * 60 * 60 * 1000);

const allMigrations = readdirSync(MIG_DIR)
  .filter((f) => f.endsWith(".sql"))
  .map((f) => ({ name: f, date: migrationDate(f) }))
  .filter((m) => m.date && m.date >= cutoff)
  .sort((a, b) => a.date - b.date);

if (allMigrations.length === 0) {
  console.log(`No migrations in the last ${DAYS} days. Nothing to check.`);
  process.exit(0);
}

const types = readFileSync(TYPES_FILE, "utf8");

// Extract symbols introduced by recent migrations.
//   CREATE TABLE [IF NOT EXISTS] public.<name>     -> table
//   ALTER TABLE [ONLY] public.<name> ADD COLUMN [IF NOT EXISTS] <col> -> column
const TABLE_RE = /create\s+table\s+(?:if\s+not\s+exists\s+)?(?:public\.)?["]?(\w+)["]?/gi;
const COLUMN_RE = /alter\s+table\s+(?:only\s+)?(?:public\.)?["]?(\w+)["]?\s+add\s+column\s+(?:if\s+not\s+exists\s+)?["]?(\w+)["]?/gi;

const expectedTables = new Set();
const expectedColumns = []; // [{table, column, source}]

for (const mig of allMigrations) {
  const sql = readFileSync(join(MIG_DIR, mig.name), "utf8");
  // Strip line comments to avoid false positives
  const stripped = sql.replace(/--[^\n]*/g, "");

  for (const m of stripped.matchAll(TABLE_RE)) {
    expectedTables.add(m[1].toLowerCase());
  }
  for (const m of stripped.matchAll(COLUMN_RE)) {
    expectedColumns.push({
      table: m[1].toLowerCase(),
      column: m[2].toLowerCase(),
      source: mig.name,
    });
  }
}

// Check presence in types.ts.
// types.ts uses: `      <table_name>: {` for each table inside `public.Tables`.
// Columns appear as `          <col_name>: <type>` inside Row/Insert/Update.
const typesLower = types.toLowerCase();

const missingTables = [];
for (const t of expectedTables) {
  // Match `<spaces><name>: {` — generous boundary check
  const re = new RegExp(`\\n\\s+${t}\\s*:\\s*\\{`, "i");
  if (!re.test(types)) missingTables.push(t);
}

const missingColumns = [];
for (const { table, column, source } of expectedColumns) {
  // First find the table block, then check column exists somewhere in it.
  // Lazy heuristic: look for "<column>:" anywhere in types.ts AND table present.
  // If table missing it'll be reported separately.
  if (missingTables.includes(table)) continue;
  const colRe = new RegExp(`\\n\\s+${column}\\s*:`, "i");
  if (!colRe.test(types)) missingColumns.push({ table, column, source });
}

if (missingTables.length === 0 && missingColumns.length === 0) {
  console.log(
    `✅ types.ts in sync with ${allMigrations.length} migration(s) from the last ${DAYS} days.`
  );
  process.exit(0);
}

console.error("❌ Drift detected between supabase/migrations and src/integrations/supabase/types.ts.");
console.error("");
console.error("`types.ts` is auto-generated by Lovable when a migration is applied.");
console.error("If a migration was merged but types weren't refreshed, the frontend will");
console.error("compile but fail at runtime.");
console.error("");

if (missingTables.length > 0) {
  console.error(`Tables created in recent migrations but absent from types.ts (${missingTables.length}):`);
  for (const t of missingTables) console.error(`  - ${t}`);
  console.error("");
}

if (missingColumns.length > 0) {
  console.error(`Columns added in recent migrations but absent from types.ts (${missingColumns.length}):`);
  for (const c of missingColumns) console.error(`  - ${c.table}.${c.column}  (from ${c.source})`);
  console.error("");
}

console.error("Resolution: re-apply the latest migration via Lovable to trigger types regeneration,");
console.error("or open a tracked issue if this is a known platform sync lag.");
process.exit(1);
